//! Actions-only actual stored account/Shared relation journal/Group WRITE peers.
use super::*;
use n::group_management::{GroupWriteOperation as Op,NativeGroupManagementConfig as GPolicy,PublicProperty,PropertyValue};
fn cfg(root:&str,port:u16)->AccountConfig{let mut c=configuration(root,port,true);c.profile.group_management=Some(GPolicy{set_properties:true,disband:true});c}
fn prepare(manager:&AccountManager,line:&str,op:Op,nonce:&str)->Result<PreparedRelationUpdate,&'static str>{let p=[PublicProperty{key:"Name",value:PropertyValue::Text("private-name")}];manager.prepare_group_management(line,1,b"1-2",op,if op==Op::SetProperties{&p}else{&[]},nonce,true,true,true)}
async fn scenario(op:Op,accepted:bool){let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(cfg(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let pline=line.clone();let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(bounded(async move{let mut p=CommonPeer::open(listener,server).await;login_host(&mut p).await;let packet=query(&mut p,op.method()).await;let r=decode_request(&packet[1..]).unwrap();assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"1-2");if op==Op::SetProperties{let fields=a.properties().unwrap();assert_eq!(fields.len(),1);assert_eq!(fields[0].key,b"Group.Org.Name");assert_eq!(fields[0].value,b"private-name");}a.finish().unwrap();assert_eq!(row(&db,&pline).1,0);assert_eq!(row(&db,&pline).2,Some(r.call_id));let mut w=Writer::new();w.boolean(accepted).unwrap();if op==Op::Disband{w.i64(i64::MIN).unwrap();w.i64(i64::MAX).unwrap();}w.bytes(b"").unwrap();p.send(&[reply(r.call_id,w.finish().expose_to_transport())]).await;rx.await.unwrap();finish_account(&mut p).await;})));
 bounded(manager.start(&line,1,100)).await.unwrap();phase(&manager,&line,"hosted").await;assert_eq!(manager.get(&line,100).await.unwrap().group_management_supported,Some(true));let p=prepare(&manager,&line,op,NONCE).unwrap();let prepared=manager.relation_intent_history(&line,128).unwrap();assert_eq!(prepared.len(),1);assert_eq!(prepared[0].state,"preparing");assert_eq!(prepared[0].management.as_ref().unwrap().operation,op.name());assert_eq!(capture(&manager,&line,1,None,NEXT,b"1_2",true,true).err(),Some("app_account_relation_preparing"));let v=bounded(manager.finish_relation_update(p)).await.unwrap();assert_eq!(v.state,if accepted{"confirmed"}else{"rejected"});assert_eq!(v.management.as_ref().unwrap().operation,op.name());assert_eq!((v.additions,v.updates,v.removals),(0,0,0));if op==Op::SetProperties{assert!(v.base_time.is_none());}else{assert_eq!(v.base_time.as_deref(),Some("-9223372036854775808"));}let same=bounded(manager.finish_relation_update(prepare(&manager,&line,op,NONCE).unwrap())).await.unwrap();assert_eq!(same.id,v.id);assert_eq!(temp.database.get_recent_app_events(Some(&line),128).unwrap().iter().filter(|e|e.event_type=="app_voice.group_management_updated").count(),1);no_other_business(&manager,&temp.database,&line);tx.send(()).unwrap();assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(peer).await.unwrap();released(&temp.database,&line);
}
#[tokio::test]async fn group_management_account_properties_commit_without_fabricated_member_counts_or_times(){Box::pin(scenario(Op::SetProperties,true)).await;}
#[tokio::test]async fn group_management_account_disband_commits_exact_signed_times_and_does_not_retry(){Box::pin(scenario(Op::Disband,true)).await;}
#[tokio::test]async fn group_management_account_false_properties_is_terminal_rejected_and_same_nonce_history(){Box::pin(scenario(Op::SetProperties,false)).await;}
#[tokio::test]async fn group_management_account_create_replace_installs_schema_only_when_explicit(){Box::pin(async{let cert=Certificates::generate("IP:127.0.0.1");let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let old=configuration(&cert.root,1,true);let account=manager.create(old,100).await.unwrap().account;let exists=||temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM sqlite_master WHERE name='app_voice_group_write_operations'",[],|r|r.get::<_,i64>(0)).map_err(|_|"fixture")).unwrap();assert_eq!(exists(),0);manager.replace(&account.line_id,1,cfg(&cert.root,1),100).await.unwrap();assert_eq!(exists(),1);assert_eq!(manager.prepare_group_management(&account.line_id,2,b"1-2",Op::Disband,&[],NONCE,true,true,false).err(),Some("app_account_relation_consent_required"));assert_eq!(manager.get(&account.line_id,100).await.unwrap().phase,"stopped");}).await;}
#[tokio::test]async fn group_management_account_membership_preparing_blocks_management_before_await(){Box::pin(async{let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(cfg(&cert.root,port),100).await.unwrap().account;let line=account.line_id.clone();let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(bounded(async move{let mut p=CommonPeer::open(listener,server).await;login_host(&mut p).await;rx.await.unwrap();finish_account(&mut p).await;})));bounded(manager.start(&line,1,100)).await.unwrap();phase(&manager,&line,"hosted").await;let held=capture(&manager,&line,1,None,NONCE,b"1_2",true,true).unwrap();assert_eq!(prepare(&manager,&line,Op::Disband,NEXT).err(),Some("app_account_relation_preparing"));drop(held);let p=prepare(&manager,&line,Op::Disband,NEXT).unwrap();drop(p);assert_eq!(rows(&temp.database,&line),0);assert!(manager.relation_intent_history(&line,128).unwrap().iter().all(|r|r.state=="not_sent"));tx.send(()).unwrap();assert!(!bounded(manager.stop(&line,1,100)).await.unwrap().io_cleanup_required);bounded(peer).await.unwrap();}).await;}
